function slice(cx,cy,r,a0,a1,color){
  var s0=[cx+r*Math.cos(a0), cy+r*Math.sin(a0)];
  var e1=[cx+r*Math.cos(a1), cy+r*Math.sin(a1)];
  var large=(a1-a0)>Math.PI?1:0;
  var d='M '+cx+' '+cy+' L '+s0[0].toFixed(2)+' '+s0[1].toFixed(2)+' A '+r+' '+r+' 0 '+large+' 1 '+e1[0].toFixed(2)+' '+e1[1].toFixed(2)+' Z';
  return '<path d="'+d+'" fill="'+color+'" stroke="#0A0A0B" stroke-width="1"/>';
}
function pieSvg(items){
  if(!Array.isArray(items)||!items.length) return {error:'至少 1 项'};
  var data=[]; var total=0;
  for(var i=0;i<items.length;i++){ var v=+items[i].value; if(isNaN(v)||v<0) return {error:'数值须为非负数字'}; total+=v; data.push({label:String(items[i].label||('项'+(i+1))), value:v}); }
  if(total<=0) return {error:'总和须为正'};
  var pal=['#5E6AD2','#10B981','#F5A623','#EF4444','#22D3EE','#A78BFA','#F472B6','#34D399'];
  var cx=100,cy=100,r=80,ang=-Math.PI/2; var parts=[];
  for(var j=0;j<data.length;j++){ var frac=data[j].value/total; var a0=ang; var a1=ang+frac*2*Math.PI; ang=a1;
    parts.push(slice(cx,cy,r,a0,a1,pal[j%pal.length])); }
  var svg='<svg viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg">'+parts.join('')+'</svg>';
  return {svg:svg, total:total};
}
var EXPORTS={pieSvg:pieSvg};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PieChartForgePure = EXPORTS; }
